#!/usr/bin/env python3
from pathlib import Path

path = Path('src/core/core_lower.c')
text = path.read_text()
marker = 'M130_DISCARD_OPERAND_TRACE'

if marker not in text:
    needle = '''        (void)fprintf(stderr,\n                      "CORE_EXPR_STMT_DETAIL function=%s route=%s expression_kind=%d "\n                      "value_category=%d\\n",\n                      context->source_function->name,\n                      route,\n                      (int)expression->kind,\n                      (int)expression->value_category);\n'''
    if needle not in text:
        raise SystemExit('expression-statement trace seam changed')
    replacement = needle + '''        /* M130_DISCARD_OPERAND_TRACE: the outer DISCARD node only says that a\n           value is intentionally ignored.  When the recursive lower fails,\n           identify the actual operand owner without changing lowering. */\n        if (expression->kind == MINIC_EXPRESSION_DISCARD &&\n            context->body != NULL && context->body->program != NULL) {\n            const MinicExpression *operand;\n            const MinicExpression *nested_operand;\n            int operand_kind = -1;\n            int operand_value_category = -1;\n            int operator_kind = -1;\n            int nested_kind = -1;\n            int direct_call = -1;\n            int argument_count = -1;\n\n            operand = minic_c0_program_expression(\n                context->body->program, expression->value.unary.operand);\n            nested_operand = NULL;\n            if (operand != NULL) {\n                operand_kind = (int)operand->kind;\n                operand_value_category = (int)operand->value_category;\n                if (operand->kind == MINIC_EXPRESSION_UNARY) {\n                    operator_kind = (int)operand->value.unary.operator_kind;\n                    nested_operand = minic_c0_program_expression(\n                        context->body->program, operand->value.unary.operand);\n                } else if (operand->kind == MINIC_EXPRESSION_BINARY ||\n                           operand->kind == MINIC_EXPRESSION_ASSIGNMENT ||\n                           operand->kind == MINIC_EXPRESSION_COMPOUND_ASSIGNMENT) {\n                    operator_kind = (int)operand->value.binary.operator_kind;\n                } else if (operand->kind == MINIC_EXPRESSION_BUILTIN_UNARY) {\n                    operator_kind = (int)operand->value.builtin_unary.operator_kind;\n                    nested_operand = minic_c0_program_expression(\n                        context->body->program, operand->value.builtin_unary.operand);\n                } else if (operand->kind == MINIC_EXPRESSION_CALL) {\n                    direct_call = operand->value.call.function_id != MINIC_FUNCTION_INVALID ? 1 : 0;\n                    argument_count = (int)operand->value.call.argument_count;\n                } else if (operand->kind == MINIC_EXPRESSION_DISCARD ||\n                           operand->kind == MINIC_EXPRESSION_CAST ||\n                           operand->kind == MINIC_EXPRESSION_BITCAST ||\n                           operand->kind == MINIC_EXPRESSION_CONVERSION ||\n                           operand->kind == MINIC_EXPRESSION_ADDRESS_OF ||\n                           operand->kind == MINIC_EXPRESSION_DEREFERENCE ||\n                           operand->kind == MINIC_EXPRESSION_LVALUE_READ) {\n                    nested_operand = minic_c0_program_expression(\n                        context->body->program, operand->value.unary.operand);\n                }\n                if (nested_operand != NULL) {\n                    nested_kind = (int)nested_operand->kind;\n                }\n            }\n            (void)fprintf(stderr,\n                          "CORE_M130_DISCARD_DETAIL function=%s operand_kind=%d "\n                          "operand_value_category=%d operator_kind=%d nested_kind=%d "\n                          "direct_call=%d argc=%d\\n",\n                          context->source_function->name,\n                          operand_kind,\n                          operand_value_category,\n                          operator_kind,\n                          nested_kind,\n                          direct_call,\n                          argument_count);\n        }\n'''
    text = text.replace(needle, replacement, 1)
    path.write_text(text)

print('M130 discard operand diagnostic staged')
